UPDATE `quest_template_locale` SET `LogDescription`='Meldet Euch bei Unteroffizier Willem hinter der Abtei von Nordhain im Wald von Elwynn.', `QuestDescription`='Ich habe eine dringliche Nachricht von Unteroffizier Willem erhalten. Wie sich herausstellt, haben die Schwarzfelsorcs goblinische Auftragsmörder angeheuert. Sie haben unser Bataillon hinter der Abtei aus dem Hinterhalt angegriffen. Willem bat mich, ihm einen Helden zu schicken. Ihr müsst ihnen helfen, $n!$B$BFindet Unteroffizier Willem nördlich der Abtei am Kommandozelt. Geht!', `PortraitGiverText`='Unteroffizier Willem befindet sich am Kommandozelt hinter der Abtei von Nordhain.', `PortraitGiverName`='Unteroffizier Willem', `VerifiedBuild`=25549 WHERE (`ID`=28789 AND `locale`='deDE');
