UPDATE `quest_template_locale` SET `QuestDescription`='Womöglich seid Ihr bereit, uns beim Kampf gegen die Verderbnis zu helfen, die das Laubschattental heimsucht.$B$BMondpriesterin Dentaria Silbertal hat uns ihre Hilfe angeboten. Ihr solltet sie zwischen den beiden Teichen nördlich unseres Großen Baumes finden. Schlagt einen Bogen um den Baum, um zu ihr zu gelangen und helft ihr so gut Ihr könnt, $C.', `VerifiedBuild`=25549 WHERE (`ID`=28723 AND `locale`='deDE');
