UPDATE `quest_template_locale` SET `QuestDescription`='Auf Anweisung seiner königlichen Hoheit König Anduin Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Leutnant Doren im Rebellenlager zu melden.$B$BAuch Jahre nach Colonel Kurzens Verrat gegen Sturmwind bleibt die Wahrheit über das, was geschehen ist, ein Rätsel. Helft den Überlebenden dabei, zu erfahren, was aus dem Colonel geworden ist. Reist vom Dämmerwald aus nach Süden und nachdem Ihr den Dschungel erreicht habt, folgt der Straße nach Westen, um zum Rebellenlager zu gelangen.$B$BFür den Ruhm und die Ehre der Allianz!', `VerifiedBuild`=25549 WHERE (`ID`=28699 AND `locale`='deDE');
