UPDATE `quest_template_locale` SET `QuestDescription`='Auf Anweisung seiner königlichen Hoheit König Anduin Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Naraat dem Erdsprecher am Östlichen Erdschrein in Sturmwind zu melden.$B$BDer Irdene Ring braucht unsere Hilfe! Uns wurde berichtet, dass die Elementarebene Tiefenheim droht, unsere Welt zu übernehmen und alles Leben in Azeroth zu zerstören!$B$BDer Östliche Erdschrein befindet sich direkt nordwestlich der Burg Sturmwind.$B$BFür den Ruhm und die Ehre der Allianz! Auf in den Kampf, $GBruder:Schwester;!', `VerifiedBuild`=25549 WHERE (`ID`=27727 AND `locale`='deDE');
UPDATE `quest_template_locale` SET `QuestDescription`='Auf Anweisung seiner königlichen Hoheit König Anduin Wrynn ergeht hiermit an alle tauglichen Mitglieder der Allianz der Befehl, sich umgehend bei Botschafterin Windweise in Nachthafen auf der Mondlichtung zu melden.$B$BUnsere Brüder im Zirkel des Cenarius haben uns berichtet, dass Todesschwinges Anhänger einen vernichtenden Angriff gegen den Weltenbaum gestartet haben und drohen, ihn zu verbrennen!$B$BSprecht mit Cenarius'' Abgesandter Jademond in der Burg Sturmwind, um Zugang zur Mondlichtung zu erlangen.$B$BFür den Ruhm und die Ehre der Allianz! Auf in den Kampf, $GBruder:Schwester;!', `PortraitGiverText`='', `VerifiedBuild`=25549 WHERE (`ID`=27726 AND `locale`='deDE');
