UPDATE `quest_template_locale` SET `LogTitle`='Keine Waffen für Grimmtotems!', `QuestDescription`='Die Grimmtotems wollen kämpfen? Mal sehen, wie sie das ohne ihre Waffen anstellen wollen. $B$BIhr habt doch sicherlich irgendwas, das brennt. Brennt ihre Waffenständer nieder, $C.$B$BLasst die Natur die Arbeit verrichten.', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=27311 AND `locale`='deDE');
