UPDATE `quest_template_locale` SET `QuestDescription`='Mankriks Wut über seine tote Frau bietet Anlass zu weiterer Sorge, $C.$B$BDie Stacheleber im Kral der Klingenhauer sind weitaus skrupelloser und hasserfüllter, als Mankrik sich je vorstellen konnte.$B$BIhr solltet nach Süden reisen und mit meinem alten Freund Auld Steinkeil sprechen. Er arbeitet daran, ihrer Raserei ein Ende zu bereiten, bevor das ohnehin geschwächte Land noch mehr leidet.', `VerifiedBuild`=25549 WHERE (`ID`=26908 AND `locale`='deDE');
