UPDATE `quest_template_locale` SET `QuestDescription`='Ich kann ihn mir nicht aus dem Kopf schlagen, $n. Manchmal in der Nacht, höre ich sein wütendes, klagendes Heulen, das über die Ebenen schallt. Mir vorzustellen, dass er da draußen ist... alleine... und solche Schmerzen leidet...$B$BBitte, ich muss Euch um einen Gefallen bitten. Geht zu Mankrik und bittet ihn, zu mir zu kommen.', `PortraitGiverText`='', `VerifiedBuild`=25549 WHERE (`ID`=24633 AND `locale`='deDE');
