UPDATE `quest_template_locale` SET `QuestDescription`='Wir können die Naga nicht ungestraft davonkommen lassen, $n. Der Mord an dem Hüter des Hains ist eine Kriegserklärung.$B$BIhr könnt ihre Höhle auf der Insel Nazj''vel weit im Südwesten finden.$B$BÜberbringt ihnen eine deutliche Nachricht.', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=13898 AND `locale`='deDE');
