UPDATE `quest_template_locale` SET `LogDescription`='Die dunkle Waldläuferin Lyana südlich des Hafens der Vergeltung möchte, dass Ihr Hauptmann Olster, Leutnant Celeyne und Unteroffizier Lorric tötet. Ihr findet sie am Verlassenen Strand.', `QuestCompletionLog`='', `VerifiedBuild`=25549 WHERE (`ID`=11233 AND `locale`='deDE');
